-- Optional: the app creates these automatically on first page load.
ALTER TABLE competitions ADD COLUMN `format` ENUM('League','Groups') NOT NULL DEFAULT 'League' AFTER `type`;
CREATE TABLE IF NOT EXISTS comp_teams (id INT UNSIGNED NOT NULL AUTO_INCREMENT, competition_id INT UNSIGNED NOT NULL, team_name VARCHAR(100) NOT NULL, group_name VARCHAR(30) DEFAULT NULL, PRIMARY KEY (id), UNIQUE KEY uq_comp_team (competition_id, team_name), CONSTRAINT fk_ct_comp FOREIGN KEY (competition_id) REFERENCES competitions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS comp_matches (id INT UNSIGNED NOT NULL AUTO_INCREMENT, competition_id INT UNSIGNED NOT NULL, stage VARCHAR(30) DEFAULT NULL, match_date DATE DEFAULT NULL, home_team VARCHAR(100) NOT NULL, away_team VARCHAR(100) NOT NULL, home_score TINYINT UNSIGNED DEFAULT NULL, away_score TINYINT UNSIGNED DEFAULT NULL, PRIMARY KEY (id), KEY idx_cm_comp (competition_id), CONSTRAINT fk_cm_comp FOREIGN KEY (competition_id) REFERENCES competitions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
